function minimumSum(num) {
  const digits = [];
  while (num > 0) {
    digits.push(num % 10);
    num = Math.floor(num / 10);
  }
  digits.sort((a, b) => a - b);
  const first = digits[0] * 10 + digits[2];
  const second = digits[1] * 10 + digits[3];
  return first + second;
}

