function minimumSum(num) {
  const chars = String(num).split('');
  let best = Infinity;
  const permute = (prefix, rest) => {
    if (!rest.length) {
      for (let cut = 1; cut < prefix.length; cut++) {
        const total = Number(prefix.slice(0, cut).join('')) + Number(prefix.slice(cut).join(''));
        if (total < best) best = total;
      }
      return;
    }
    for (let i = 0; i < rest.length; i++) permute([...prefix, rest[i]], [...rest.slice(0, i), ...rest.slice(i + 1)]);
  };
  permute([], chars);
  return best;
}

