function generate(rand, size) {
  if (size === 'small' && rand() < 0.4) {
    // Favour repeated digits and zeros, where mistakes show up.
    const pool = [0, 0, 1, 9, Math.floor(rand() * 10)];
    const d = [1 + Math.floor(rand() * 9)];
    for (let i = 0; i < 3; i++) d.push(pool[Math.floor(rand() * pool.length)]);
    return [Number(d.join(''))];
  }
  return [1000 + Math.floor(rand() * 9000)];
}
